import numpy as np
P=df['P'].values; T=df['t'].values; y=df['dP_dt'].values
var=np.var(y)
base={'P':P,'P2':P**2,'P3':P**3,'tP':T*P,'tP2':T*P**2,'t':T,'1':np.ones_like(T),'sqrtP':np.sqrt(T)*P,'sqrtP2':np.sqrt(T)*P**2,'t2':T**2}
names=list(base)
shapes={
 '1-exp(-kP)': lambda k: 1-np.exp(-k*P),
 'P/(1+kP)': lambda k: P/(1+k*P),
 'P*exp(-kP)': lambda k: P*np.exp(-k*P),
 'P/sqrt(1+kP^2)': lambda k: P/np.sqrt(1+k*P**2),
 'tanh(kP)': lambda k: np.tanh(k*P),
}
for sn,sf in shapes.items():
  res=[]
  for k in np.concatenate([np.logspace(-3,1.5,80)]):
    for pe in [0.5]:
      f=np.sqrt(T)*sf(k)
      X=np.column_stack([f]+[base[n] for n in names])
      c=np.linalg.lstsq(X,y,rcond=None)[0]
      res.append((np.mean((y-X@c)**2)/var,k,c))
  res.sort(key=lambda r:r[0])
  print(sn,'NMSE=%.3e k=%.4f'%(res[0][0],res[0][1]), np.round(res[0][2],4))
